import sys, json
sys.path.insert(0, '/tmp/qdk41')
from data import ROWS

MAU_TO_UMS = 0.3092 / 60.0   # mAU/min -> uM/s (header conversion)
DILUTION_SCALE = {'C5': 1000 / 500}  # MM-13 used 1:1000 for all C5 wells; rescale to 1:500

def conv(v, unit):
    if unit == 'mAU':
        return v * MAU_TO_UMS
    if unit == 'uMmin':
        return v / 60.0
    if unit == 'nMs':
        return v / 1000.0
    raise ValueError(unit)

wells = []
excluded = []
for line in ROWS.splitlines():
    if not line or line.startswith('#'):
        continue
    sid, cond, s, val, unit, flag = line.split()
    rate = conv(float(val), unit) * DILUTION_SCALE.get(cond, 1.0)
    if flag == 'X':
        excluded.append(sid)
    else:
        wells.append((sid, cond, float(s), rate))

def fit_mm(pts, vmax_fixed=None):
    """Unweighted NLS of v = V*S/(K+S) by Gauss-Newton with step halving (2 params) or 1-param (V fixed)."""
    S = [p[2] for p in pts]; v = [p[3] for p in pts]
    V = max(v) if vmax_fixed is None else vmax_fixed
    K = 0.5 * sum(S) / len(S)
    def sse(V, K):
        return sum((vi - V*si/(K+si))**2 for si, vi in zip(S, v))
    for _ in range(500):
        # Jacobian of model wrt V and K
        JtJ = [[0.0, 0.0], [0.0, 0.0]]; Jtr = [0.0, 0.0]
        for si, vi in zip(S, v):
            f = V*si/(K+si)
            dV = si/(K+si); dK = -V*si/(K+si)**2
            r = vi - f
            JtJ[0][0] += dV*dV; JtJ[0][1] += dV*dK; JtJ[1][1] += dK*dK
            Jtr[0] += dV*r; Jtr[1] += dK*r
        JtJ[1][0] = JtJ[0][1]
        if vmax_fixed is None:
            det = JtJ[0][0]*JtJ[1][1] - JtJ[0][1]*JtJ[1][0]
            dVs = ( JtJ[1][1]*Jtr[0] - JtJ[0][1]*Jtr[1]) / det
            dKs = (-JtJ[1][0]*Jtr[0] + JtJ[0][0]*Jtr[1]) / det
        else:
            dVs = 0.0
            dKs = Jtr[1] / JtJ[1][1]
        step = 1.0
        base = sse(V, K)
        while step > 1e-12:
            nV, nK = V + step*dVs, K + step*dKs
            if nK > 0 and nV > 0 and sse(nV, nK) <= base:
                break
            step /= 2
        if step <= 1e-12:
            break
        V, K = nV, nK
        if abs(step*dKs) < 1e-14 and abs(step*dVs) < 1e-14:
            break
    return V, K, sse(V, K)

conds = ['C1','C2','C3','C4','C5','C6','C7']
inhib_map = {'C4': 'C1', 'C6': 'C5'}   # same pH/temp no-inhibitor condition
results = {}
for c in ['C1','C2','C3','C5','C7']:
    pts = [w for w in wells if w[1] == c]
    V, K, sse = fit_mm(pts)
    results[c] = (V, K)
    print(c, 'n=%d' % len(pts), 'Vmax=%.6f uM/s' % V, 'Km=%.4f uM' % K, 'SSE=%.3e' % sse)
for c, ref in inhib_map.items():
    pts = [w for w in wells if w[1] == c]
    V = results[ref][0]
    _, K, sse = fit_mm(pts, vmax_fixed=V)
    results[c] = (V, K)
    print(c, 'n=%d' % len(pts), 'Vmax(shared from %s)=%.6f' % (ref, V), 'apparent Km=%.4f uM' % K, 'SSE=%.3e' % sse)

out = {'conditions': [{'condition_id': c, 'vmax': round(results[c][0], 6), 'km': round(results[c][1], 4)} for c in conds],
       'excluded_samples': sorted(excluded)}
print(json.dumps(out, indent=1))
json.dump(out, open('/tmp/qdk41/result.json', 'w'), indent=1)

import sys, json
sys.path.insert(0, '/tmp/qdk41')
import fit  # reruns fit and prints; reuse wells
res = json.load(open('/tmp/qdk41/result.json'))
R = {c['condition_id']: (c['vmax'], c['km']) for c in res['conditions']}
def sse(pts, V, K):
    return sum((p[3] - V*p[2]/(K+p[2]))**2 for p in pts)
for c in ['C1','C2','C3','C5','C7']:
    pts = [w for w in fit.wells if w[1] == c]
    V0, K0 = R[c]
    best = min(((sse(pts, V0*(1+dv/1000), K0*(1+dk/1000)), dv, dk) for dv in range(-30,31,2) for dk in range(-30,31,2)))
    print(c, 'local grid min at dV=%+.1f%% dK=%+.1f%%' % (best[1]/10, best[2]/10), 'sse-ratio=%.6f' % (best[0]/sse(pts,V0,K0)))
